<template><section data-analytics-ignore><h3>Your app sign-in password</h3><p>Prepare a password for signing in without Google when your agency switches to app-only email. Setting a password does not turn off SSO.</p><p v-if="hasPassword">Your account already has a password. <a href="/change-password" target="_blank" rel="noopener">Change password ↗</a></p><form v-else-if="hasPassword===false" @submit.prevent="save"><p>Set your first app password within five minutes of verifying with Google.</p><label>New password<input v-model="password" type="password" autocomplete="new-password" required minlength="14" maxlength="256" /></label><label>Confirm new password<input v-model="confirm" type="password" autocomplete="new-password" required /></label><button :disabled="busy">Set my app password</button></form><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p></section></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import api from '../services/api';const props=defineProps({expectedUserId:[Number,String]});const securityHeaders=()=>({'X-Account-Security':'1',...(props.expectedUserId?{'X-Account-User-Id':String(props.expectedUserId)}:{})});const hasPassword=ref(null),password=ref(''),confirm=ref(''),error=ref(''),message=ref(''),busy=ref(false);
onMounted(async()=>{try{hasPassword.value=(await api.get('/account-security/sign-in-password',{headers:securityHeaders(),...(props.expectedUserId?{cookieAuthOnly:true,skipAuthRedirect:true}:{})})).data.hasPassword;}catch(e){error.value=e.response?.data?.error?.message||'Sign in to your own account to manage passwords.';}});
async function save(){if(password.value!==confirm.value){error.value='The passwords do not match.';return;}busy.value=true;error.value='';try{await api.post('/account-security/sign-in-password',{newPassword:password.value},{headers:securityHeaders(),...(props.expectedUserId?{cookieAuthOnly:true,skipAuthRedirect:true}:{})});hasPassword.value=true;message.value='App password saved. Keep using SSO until your agency switches your account. Store this password safely in your password manager.';}catch(e){error.value=e.response?.data?.error?.message||'Unable to set your password.';}finally{password.value='';confirm.value='';busy.value=false;}}
onBeforeUnmount(()=>{password.value='';confirm.value='';});
</script><style scoped>section,form,label{display:grid;gap:10px}input{padding:10px;max-width:460px;font:inherit}button{width:fit-content;padding:10px 16px}</style>
